mb:micro.mb:pseudocode:
const KINDS = new Set([...8 kinds...]);
createAnnouncer(container):
    region = <div aria-live="polite" aria-atomic="true" class="visually-hidden">
    container.appendChild(region)
    let last = "";
    announce(kind, message):
        if (!KINDS.has(kind)) throw new RangeError(`unknown announce kind: ${kind}`);
        region.textContent = (message === last) ? message + "​" : message;
        last = message;

const step = {up:[-1,0], down:[1,0], left:[0,-1], right:[0,1]};
moveSelection(from, direction, modifier):
    let r = (from / 9) | 0, c = from % 9;
    if (direction === "lineStart") return modifier === "ctrl" ? 0  : r * 9;
    if (direction === "lineEnd")   return modifier === "ctrl" ? 80 : r * 9 + 8;
    const [dr, dc] = step[direction];
    const n = modifier === "ctrl" ? 3 : 1;
    r = clamp(r + dr * n, 0, 8);
    c = clamp(c + dc * n, 0, 8);
    return r * 9 + c;
// clamp, not wrap: an unreachable edge must not teleport the caret across the board

mb:micro.mb:input-type:
cellLabel(state: {
  index: number, given: number, value: number, candidates: number,
  conflict: boolean, hasNote: boolean
}) -> string

mb:micro.mb:pseudocode:
cellLabel(s):
    validate(s)
    const parts = [`${((s.index/9)|0)+1}행 ${(s.index%9)+1}열`];
    if (s.given)      parts.push(`고정 숫자 ${s.given}`);
    else if (s.value) parts.push(`${s.value}`);
    else              parts.push("빈 칸");
    if (s.candidates) parts.push(`후보 ${digitsOf(s.candidates).join(", ")}`);
    if (s.conflict)   parts.push("규칙 위반");
    if (s.hasNote)    parts.push("메모 있음");
    return parts.join(", ");

updateCell(i):
    const cell = cells[i];
    cell.dataset.given    = givens[i] ? "1" : "0";
    cell.dataset.conflict = conflicts.has(i) ? "1" : "0";
    cell.dataset.note     = hasNote(i) ? "1" : "0";
    valueNode(cell).textContent = String(givens[i] || values[i] || "");
    renderCandidates(cell, candidates[i]);        // 9 fixed spans, textContent only
    cell.setAttribute("aria-label", cellLabel(snapshotOf(i)));
// never innerHTML: note text is user input and is rendered elsewhere by UI-B10,
// but the same rule is enforced here so the board can never become an injection path

def contradiction_proven(board, index, value, spec, max_depth=1):
    validate(board, index, value, spec)
    work = list(board); work[index] = value
    for _ in range(max_depth):
        singles = []
        for i, cell in enumerate(work):
            if cell: continue
            allowed = [v for v in range(1, spec.dim + 1)
                       if not spec.peers_forbid(work, i, v)]
            if not allowed:
                return True                 # proven: a cell has no candidate left
            if len(allowed) == 1:
                singles.append((i, allowed[0]))
        if not singles:
            return False                    # nothing more to deduce, stay conservative
        for i, v in singles:
            if spec.peers_forbid(work, i, v):
                return True                 # two singles collided
            work[i] = v
    return False

for dim, trials in ((9, 40), (12, 5)):
    for _ in range(trials):
        puzzle, solution = generate_puzzle(dim=dim, rng=seeded)
        assert reference.count_solutions(puzzle, dim, limit=2) == 1   # independent oracle
        assert solver.solve(puzzle, dim) == solution

