@classmethod
def reduced(cls, spec, board):
    allowed = per-cell candidate sets derived from the clues
    if any cell has an empty set: return None            # contradictory clues
    build the matrix including only rows in `allowed`
    node count is no longer the fixed 1 + 4*dim^2 + 4*dim^3, so size is computed first

